using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
public static class SwitchPlayerSupportProbe
{
    private const string SceneName = "SwitchPlayerSupportProbe";
    private static void Require(bool result, string message)
    {
        if (!result) throw new Exception(message);
        Debug.Log("[SwitchPlayerSupport] PASS: " + message);
    }
    public static string Begin()
    {
        if (!EditorApplication.isPlaying) throw new Exception("Play Mode required.");
        SessionState.SetBool("SwitchSupport.Background", Application.runInBackground);
        Application.runInBackground = true;
        var scene = SceneManager.CreateScene(SceneName, new CreateSceneParameters(LocalPhysicsMode.Physics2D));
        var physics = scene.GetPhysicsScene2D();
        var root = UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Gimmicks/WeightSwitch.prefab"));
        root.name = "SupportSwitch";
        SceneManager.MoveGameObjectToScene(root, scene);
        root.transform.position = Vector3.zero;
        var sw = root.GetComponent<WeightSwitch>();
        var cap = root.transform.Find("Visual/PressureCap").GetComponent<BoxCollider2D>();
        var plinth = root.transform.Find("Visual").GetComponent<BoxCollider2D>();
        Require(cap != null && plinth != null && !cap.isTrigger && !plinth.isTrigger, "Base and raised cap have solid support colliders");
        int mask = LayerMask.GetMask("player");
        Require(cap.includeLayers.value == mask && cap.excludeLayers.value == ~mask && cap.gameObject.CompareTag("Floor"), "Support accepts only the existing player layer and is valid ground");
        var actor = new GameObject("SupportPlayer");
        actor.layer = LayerMask.NameToLayer("player");
        actor.tag = "Player";
        SceneManager.MoveGameObjectToScene(actor, scene);
        actor.transform.position = new Vector3(0f, 6f, 0f);
        var capsule = actor.AddComponent<CapsuleCollider2D>();
        capsule.size = new Vector2(1f, 3.3f);
        var body = actor.AddComponent<Rigidbody2D>();
        body.constraints = RigidbodyConstraints2D.FreezeRotation;
        body.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
        Physics2D.SyncTransforms();
        for (int i=0;i<160;i++) physics.Simulate(0.02f);
        Require(capsule.IsTouching(cap) && Mathf.Abs(capsule.bounds.min.y-cap.bounds.max.y)<0.05f, "Player-sized capsule lands on the raised button without falling through");
        Require(!sw.IsPressed && root.GetComponent<Collider2D>().enabled, "Standing Player does not press the button or consume its trigger");
        var feet = (Vector2)capsule.bounds.center;
        feet.y = capsule.bounds.min.y-0.03f;
        var filter = new ContactFilter2D();
        filter.SetLayerMask(LayerMask.GetMask("Default","Walls"));
        filter.useTriggers = false;
        var hits = new Collider2D[8];
        Require(physics.OverlapBox(feet,new Vector2(0.72f,0.12f),0f,filter,hits)>0, "Support is detectable by the Player ground-check layer mask");
        var ball = new GameObject("SupportMorningStar");
        ball.layer = LayerMask.NameToLayer("morningstar");
        ball.tag = "morningstar";
        SceneManager.MoveGameObjectToScene(ball, scene);
        ball.transform.position = new Vector3(0.8f, 4.5f, 0f);
        var circle = ball.AddComponent<CircleCollider2D>();
        circle.radius=0.3f;
        var ballBody = ball.AddComponent<Rigidbody2D>();
        ballBody.gravityScale=0f;
        ballBody.linearVelocity=Vector2.down*4f;
        Physics2D.IgnoreCollision(circle,capsule,true);
        Physics2D.SyncTransforms();
        for(int i=0;i<110;i++) physics.Simulate(0.02f);
        Require(sw.IsPressed && !root.GetComponent<Collider2D>().enabled, "Morning Star still triggers the one-shot switch");
        Require(ballBody.position.y<plinth.bounds.min.y-0.5f, "Player-only support does not block the Morning Star detector");
        File.WriteAllText("output/switch-player-collision/begin.txt","PASS: raised Player support, ground mask, no Player activation, Morning Star activation and passage");
        return "PASS: support and iron-ball detection. Wait for the normal press animation, then Complete.";
    }
    public static string Complete()
    {
        var scene=SceneManager.GetSceneByName(SceneName);
        var physics=scene.GetPhysicsScene2D();
        var roots=scene.GetRootGameObjects();
        var root=roots.First(x=>x.name=="SupportSwitch");
        var actor=roots.First(x=>x.name=="SupportPlayer");
        var body=actor.GetComponent<Rigidbody2D>();
        var capsule=actor.GetComponent<Collider2D>();
        var sw=root.GetComponent<WeightSwitch>();
        var cap=root.transform.Find("Visual/PressureCap").GetComponent<BoxCollider2D>();
        Require(sw.IsPressed && !cap.GetComponent<SpriteRenderer>().enabled && cap.enabled, "Pressed artwork retains its solid support");
        Require(Mathf.Abs(cap.transform.localPosition.y+0.4875f)<0.001f, "Support moves exactly to the pressed cap height");
        body.position=new Vector2(0f,5f);
        body.linearVelocity=Vector2.zero;
        Physics2D.SyncTransforms();
        for(int i=0;i<160;i++) physics.Simulate(0.02f);
        Require(capsule.IsTouching(cap) && Mathf.Abs(capsule.bounds.min.y-cap.bounds.max.y)<0.05f, "Player can stand on the depressed button too");
        Require(sw.IsPressed && !root.GetComponent<Collider2D>().enabled, "Pressed switch stays ON under the Player");
        Application.runInBackground=SessionState.GetBool("SwitchSupport.Background",false);
        File.WriteAllText("output/switch-player-collision/validation.txt","PASS: raised support, grounded detection, no Player activation, Morning Star activation and passage, lowered support, one-shot latch; no production input/physics settings changed.");
        SceneManager.UnloadSceneAsync(scene);
        return File.ReadAllText("output/switch-player-collision/validation.txt");
    }
}
